import sqlite3, json
conn = sqlite3.connect('world.db')

# Check flight FLD3D594
cursor = conn.execute(\"SELECT * FROM flights WHERE flight_id = 'FLD3D594'\")
cols = [d[0] for d in cursor.description]
row = cursor.fetchone()
if row:
    for c, v in zip(cols, row):
        if c.endswith('_json'):
            print(f'{c}: {json.dumps(json.loads(v), indent=2)[:500]}')
        else:
            print(f'{c}: {v}')
else:
    print('Flight FLD3D594 not found')
"

